static uint32_t backColorRGB = 0xFFFFFF;

static inline uint8_t fs_getColorValue(const uint8_t fore, const uint8_t back, const uint8_t pixelVal, const float alpha)
{
    uint8_t colorValue;

    if (fore < back)
    {
        if ((fore == 0) && (back == 0xFF))
        {
            colorValue = pixelVal;
        }
        else
        {
            colorValue = (uint8_t)(fore + (uint8_t)((back - fore) * alpha));
        }
    }
    else
    {
        colorValue = (uint8_t)(fore - (uint8_t)((fore - back) * alpha));
    }

    return colorValue;
}

static inline uint16_t fs_getColor(const uint32_t foreColor, const uint32_t backColor, const uint8_t pixelValue)
{
    uint16_t color;

    if (pixelValue == 0)
    {
        const uint8_t r = (foreColor & 0x00FF0000u) >> 16;
        const uint8_t g = (foreColor & 0x0000FF00u) >> 8;
        const uint8_t b = foreColor & 0x000000FFu;

        color = fs_getRGB565(r, g, b);
    }
    else if (pixelValue == 0xFF)
    {
        const uint8_t r = (backColor & 0x00FF0000u) >> 16;
        const uint8_t g = (backColor & 0x0000FF00u) >> 8;
        const uint8_t b = backColor & 0x000000FFu;

        color = fs_getRGB565(r, g, b);
    }
    else
    {
        const uint8_t foreR = (foreColor & 0x00FF0000u) >> 16;
        const uint8_t foreG = (foreColor & 0x0000FF00u) >> 8;
        const uint8_t foreB = foreColor & 0x000000FFu;

        const uint8_t backR = (backColor & 0x00FF0000u) >> 16;
        const uint8_t backG = (backColor & 0x0000FF00u) >> 8;
        const uint8_t backB = backColor & 0x000000FFu;

        const float alpha = pixelValue / 255.0f;

        const uint8_t r = fs_getColorValue(foreR, backR, pixelValue, alpha);
        const uint8_t g = fs_getColorValue(foreG, backG, pixelValue, alpha);
        const uint8_t b = fs_getColorValue(foreB, backB, pixelValue, alpha);

        color = fs_getRGB565(r, g, b);
    }

    return color;
}

static inline void fs_setColorPalette(const uint32_t fore, const uint32_t back)
{
    foreColorRGB = fore;
    backColorRGB = back;

    for (uint8_t i = 1; i < 16; i++)
    {
        customColorPalette565[i] = fs_getColor(fore, back, colorPalette[i]);
    }

    customColorPalette565[16] = fs_getColor(fore, back, colorPalette[16]);
    customColorPalette565[17] = fs_getColor(fore, back, colorPalette[17]);
}

static inline void fs_addPixels(uint16_t *restrict p_buffer, const uint32_t writeIndex, uint16_t noOfPixels, uint16_t color)
{
    for (uint32_t i = writeIndex; i < (writeIndex + noOfPixels); i++)
    {
        p_buffer[i] = color;
    }
}

static inline void fs_getNextPixelData(fs_pixeldata_info_s *p_pixelDataInfo, uint8_t *p_noOfPixels, uint16_t *p_color)
{
    const uint8_t data = (pixeldata[p_pixelDataInfo->readIndex]);

    if (data == 0)
    {
        *p_color = customColorPalette565[16];
        *p_noOfPixels = (pixeldata[p_pixelDataInfo->readIndex + 1]);
        p_pixelDataInfo->readIndex += 2;
    }
    else if (data == 0x0F)
    {
        *p_color = customColorPalette565[17];
        *p_noOfPixels = (pixeldata[p_pixelDataInfo->readIndex + 1]);
        p_pixelDataInfo->readIndex += 2;
    }
    else
    {
        *p_noOfPixels = (data & 0xF0) >> 4;
        *p_color = customColorPalette565[data & 0x0F];
        p_pixelDataInfo->readIndex += 1;
    }
}

void fs_read(uint16_t *restrict p_buffer, const uint32_t bufferLength, fs_pixeldata_info_s *p_pixelDataInfo)
{
    uint32_t writeIndex = 0;

    if (p_pixelDataInfo->noOfPixelsLeft > 0)
    {
        if (p_pixelDataInfo->noOfPixelsLeft <= bufferLength)
        {
            fs_addPixels(p_buffer, writeIndex, p_pixelDataInfo->noOfPixelsLeft, p_pixelDataInfo->colorPixelLeft);
            writeIndex += p_pixelDataInfo->noOfPixelsLeft;
            p_pixelDataInfo->pixelsToRead -= p_pixelDataInfo->noOfPixelsLeft;
            p_pixelDataInfo->noOfPixelsLeft = 0;
        }
        else
        {
            fs_addPixels(p_buffer, writeIndex, bufferLength, p_pixelDataInfo->colorPixelLeft);
            writeIndex += bufferLength;
            p_pixelDataInfo->pixelsToRead -= bufferLength;
            p_pixelDataInfo->noOfPixelsLeft -= bufferLength;

            return;
        }
    }
    else
    {
        if ((p_pixelDataInfo->foreColor != foreColorRGB) || (p_pixelDataInfo->backColor != backColorRGB))
        {
            fs_setColorPalette(p_pixelDataInfo->foreColor, p_pixelDataInfo->backColor);
        }
    }

    while (p_pixelDataInfo->pixelsToRead > 0)
    {
        uint8_t noOfPixels = 0;
        uint16_t color = 0;

        fs_getNextPixelData(p_pixelDataInfo, &noOfPixels, &color);

        if (p_pixelDataInfo->pixelsToRead > noOfPixels)
        {
            fs_addPixels(p_buffer, writeIndex, noOfPixels, color);
            writeIndex += noOfPixels;
            p_pixelDataInfo->pixelsToRead -= noOfPixels;
        }
        else if (p_pixelDataInfo->pixelsToRead < noOfPixels)
        {
            fs_addPixels(p_buffer, writeIndex, p_pixelDataInfo->pixelsToRead, color);
            writeIndex += p_pixelDataInfo->pixelsToRead;
            p_pixelDataInfo->noOfPixelsLeft = noOfPixels - p_pixelDataInfo->pixelsToRead;
            p_pixelDataInfo->colorPixelLeft = color;
            p_pixelDataInfo->pixelsToRead = 0;
        }
        else
        {
            fs_addPixels(p_buffer, writeIndex, noOfPixels, color);
            writeIndex += noOfPixels;
            p_pixelDataInfo->pixelsToRead = 0;
            p_pixelDataInfo->noOfPixelsLeft = 0;
        }
    }
}


void fs_transferPixels(fs_pixeldata_info_s *p_pixelDataInfo, void (*transferPixels)(const uint16_t color, const int32_t noOfpixels))
{
    uint32_t pixelsToTransfer = p_pixelDataInfo->pixelsToRead;

    if ((p_pixelDataInfo->foreColor != foreColorRGB) || (p_pixelDataInfo->backColor != backColorRGB))
    {
        fs_setColorPalette(p_pixelDataInfo->foreColor, p_pixelDataInfo->backColor);
    }
    while (pixelsToTransfer > 0)
    {
        uint8_t noOfPixels = 0;
        uint16_t color = 0;

        fs_getNextPixelData(p_pixelDataInfo, &noOfPixels, &color);
        transferPixels(color, noOfPixels);

        if (pixelsToTransfer > noOfPixels)
        {
            pixelsToTransfer -= noOfPixels;
        }
        else
        {
            pixelsToTransfer = 0;
        }
    }
}

uint16_t fs_getPixelColor(const uint32_t foreColor, const uint32_t backColor, const uint8_t pixelValue)
{
    return fs_getColor(foreColor, backColor, pixelValue);
}

